import React, { useEffect, useRef, useState } from "react";
import { FiMenu, FiX } from "react-icons/fi";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import { Link } from "gatsby";
import LanguageSelector from "./languageSelector";
import data from "../data/data.json";
import Logo from "./logo";

export default function Navigation() {
  const { t } = useTranslation();
  const { language } = useI18next();
  const [isOpen, setIsOpen] = useState(false);
  const [isServicesOpen, setIsServicesOpen] = useState(false);
  const [isServicesMobileOpen, setIsServicesMobileOpen] = useState(false);
  const servicesRef = useRef<HTMLDivElement | null>(null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const rafRef = useRef<number | null>(null);
  const menuItems = menuData.menu;
  const servicesMenu = menuData.servicesMenu || [];
  const homeHref = `/${language}/`;
  const servicesHubHref = `/${language}/services/`;

  const getServiceHref = (service: { path?: Record<string, string> }) => {
    const raw = service.path?.[language] || service.path?.en || "/";
    const cleaned = raw.replace(/^\/(en|fr)(?=\/)/, "");
    const withSlash = cleaned.startsWith("/") ? cleaned : `/${cleaned}`;
    return `/${language}${withSlash === "/" ? "" : withSlash}`;
  };

  useEffect(() => {
    if (typeof window === "undefined") {
      return undefined;
    }

    const sections = menuItems
      .map((item) => document.getElementById(item))
      .filter((section): section is HTMLElement => Boolean(section));

    if (!sections.length) {
      return undefined;
    }

    const updateActive = () => {
      if (rafRef.current) {
        return;
      }

      rafRef.current = window.requestAnimationFrame(() => {
        rafRef.current = null;
        const offset = 140;
        const scrollPosition = window.scrollY + offset;
        let currentId: string | null = sections[0]?.id || null;

        sections.forEach((section) => {
          if (section.offsetTop <= scrollPosition) {
            currentId = section.id;
          }
        });

        setActiveId(currentId);
      });
    };

    updateActive();
    window.addEventListener("scroll", updateActive, { passive: true });
    window.addEventListener("resize", updateActive);

    return () => {
      window.removeEventListener("scroll", updateActive);
      window.removeEventListener("resize", updateActive);
      if (rafRef.current) {
        window.cancelAnimationFrame(rafRef.current);
      }
    };
  }, [menuItems]);

  useEffect(() => {
    if (!isServicesOpen) {
      return undefined;
    }

    const handleClickOutside = (event: MouseEvent) => {
      if (servicesRef.current && !servicesRef.current.contains(event.target as Node)) {
        setIsServicesOpen(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsServicesOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isServicesOpen]);

  return (
    <div className="w-full border-b border-neutral/20 bg-secondary/80 backdrop-blur">
      <div className="w-full px-4 sm:px-8 lg:px-12 py-3 flex items-center justify-between gap-4">
        <Link to={homeHref} className="w-32">
          <Logo color="fill-secondary" />
        </Link>
        <nav className="hidden sm:flex items-center gap-5 text-sm">
          {menuItems.map((item, index) => {
            if (item === "services" && servicesMenu.length) {
              return (
                <div key={index} ref={servicesRef} className="relative">
                  <button
                    type="button"
                    className={`text-neutral hover:text-accent inline-flex items-center gap-1 ${activeId === item ? "text-accent font-semibold border-b-2 border-accent" : ""}`}
                    onClick={() => {
                      setActiveId(item);
                      setIsServicesOpen((prev) => !prev);
                    }}
                    aria-label={`${t(`menu.${item}`)} menu`}
                    aria-haspopup="true"
                    aria-expanded={isServicesOpen}
                  >
                    {t(`menu.${item}`)}
                    <span aria-hidden="true">▾</span>
                  </button>
                  <div
                    className={`absolute left-0 top-full mt-2 min-w-[16rem] rounded-xl border border-neutral/20 bg-secondary/95 p-2 shadow-lg backdrop-blur ${isServicesOpen ? "block" : "hidden"}`}
                  >
                    <Link
                      to={servicesHubHref}
                      className="block rounded-lg px-3 py-2 text-sm font-semibold text-accent hover:bg-primary/40"
                      onClick={() => setIsServicesOpen(false)}
                    >
                      {t("menu.allServices")}
                    </Link>
                    {servicesMenu.map((service: { key: string; path: Record<string, string> }) => {
                      const href = getServiceHref(service);
                      return (
                        <Link
                          key={service.key}
                          to={href}
                          className="block rounded-lg px-3 py-2 text-sm text-neutral hover:text-accent hover:bg-primary/40"
                          onClick={() => setIsServicesOpen(false)}
                        >
                          {t(`services.${service.key}.h1`)}
                        </Link>
                      );
                    })}
                  </div>
                </div>
              );
            }

            return (
              <a
                key={index}
                href={item === "home" ? homeHref : `${homeHref}#${item}`}
                className={`text-neutral hover:text-accent ${activeId === item ? "text-accent font-semibold border-b-2 border-accent" : ""}`}
                onClick={() => setActiveId(item)}
              >
                {t(`menu.${item}`)}
              </a>
            );
          })}
        </nav>

      {/* Mobile Menu Button */}
      <button onClick={() => setIsOpen(!isOpen)} className="md:hidden">
        {!isOpen ? <FiMenu size={24} /> : <FiX size={24} />}
      </button>
        {/* Minimal language indicator (swap for your selector) */}
        <div className="text-xs text-neutral">
          <span className="sr-only">Language</span>
          <LanguageSelector data={data} />
        </div>
      </div>


      {/* Mobile Menu */}
      {isOpen && (
        <ul className="bg-primary md:hidden shadow-md p-4 space-y-2">
          {menuItems.map((item, index) => {
            if (item === "services" && servicesMenu.length) {
              return (
                <div key={index} className="space-y-2">
                  <button
                    type="button"
                    className={`text-neutral hover:text-accent flex w-full py-4 text-center justify-center ${activeId === item ? "text-accent font-semibold" : ""}`}
                    onClick={() => {
                      setActiveId(item);
                      setIsServicesMobileOpen((prev) => !prev);
                    }}
                    aria-label={`${t(`menu.${item}`)} menu`}
                    aria-haspopup="true"
                    aria-expanded={isServicesMobileOpen}
                  >
                    {t(`menu.${item}`)}
                  </button>
                  {isServicesMobileOpen ? (
                    <div className="flex flex-col gap-2 px-4">
                      <Link
                        to={servicesHubHref}
                        className="rounded-lg bg-secondary px-3 py-2 text-center text-sm font-semibold text-accent hover:text-accent"
                        onClick={() => setIsOpen(false)}
                      >
                        {t("menu.allServices")}
                      </Link>
                      {servicesMenu.map((service: { key: string; path: Record<string, string> }) => {
                        const href = getServiceHref(service);
                        return (
                        <Link
                            key={service.key}
                            to={href}
                            className="rounded-lg bg-secondary px-3 py-2 text-center text-sm text-neutral hover:text-accent"
                            onClick={() => setIsOpen(false)}
                          >
                            {t(`services.${service.key}.h1`)}
                          </Link>
                        );
                      })}
                    </div>
                  ) : null}
                </div>
              );
            }

            return (
              <a
                key={index}
                href={item === "home" ? homeHref : `${homeHref}#${item}`}
                className={`text-neutral hover:text-accent flex py-4 text-center justify-center ${activeId === item ? "text-accent font-semibold" : ""}`}
                onClick={() => {
                  setActiveId(item);
                  setIsOpen(!isOpen);
                }}
              >
                {t(`menu.${item}`)}
              </a>
            );
          })}
        </ul>
      )}
    </div>
  );
}
