import React, { ReactNode } from "react";
import { useLocation } from "@reach/router";
import { Link } from "gatsby";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { BsGithub } from "react-icons/bs";
import { FaLinkedin } from "react-icons/fa";
import {
  FaSquareFacebook,
  FaSquarePhone,
  FaSquareWhatsapp,
} from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import images from "../images";
import data from "../data/data.json";
import { restoreLanguageSwitchScrollState } from "../utils/languageScroll";

interface LayoutProps {
  children: ReactNode;
  data?: UserProfile;
  hideChromeOnPrint?: boolean;
}

interface FooterContent {
  followUs: string;
  resumeEn: string;
  resumeFr: string;
}

const userData: UserProfile = data;

const Layout: React.FC<LayoutProps> = ({
  children,
  data,
  hideChromeOnPrint = false,
}) => {
  const { t } = useTranslation();
  const location = useLocation();
  const footerContent: FooterContent = t(
    "footer",
    { returnObjects: true }
  ) || { followUs: "", resumeEn: "", resumeFr: "" };
  const [currentYear, setYear] = React.useState<number | null>(null);
  const resumeLinks = [
    { href: "/en/resume/", label: footerContent.resumeEn },
    { href: "/fr/resume/", label: footerContent.resumeFr },
  ];

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  React.useEffect(() => {
    if (typeof window === "undefined") {
      return undefined;
    }

    let frameOne = 0;
    let frameTwo = 0;

    frameOne = window.requestAnimationFrame(() => {
      frameTwo = window.requestAnimationFrame(() => {
        restoreLanguageSwitchScrollState();
      });
    });

    return () => {
      window.cancelAnimationFrame(frameOne);
      window.cancelAnimationFrame(frameTwo);
    };
  }, [location.pathname]);

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <>
      <div
        className={`fixed inset-0 bg-no-repeat bg-cover bg-center before:content-[''] before:absolute before:inset-0 before:bg-white/80 ${
          hideChromeOnPrint ? "print:hidden" : ""
        }`}
      ></div>
      <div id={data?.menu[0]} className={styles.container}>
        <div
          className={`${hideChromeOnPrint ? "print:hidden " : ""}sticky top-0 z-40`}
        >
          <Navigation />
        </div>
        <div className="relative">{children}</div>
      </div>

      <footer
        className={`${styles.footerContainer} ${
          hideChromeOnPrint ? "print:hidden" : ""
        }`}
        id={userData.menu[4]}
      >
        <div className="flex flex-col sm:flex-row py-6">
 

          <div className="flex flex-col w-full self-center">
            <a
              href={`mailto:${data?.email}`}
              className="flex flex-row gap-2 justify-center items-center text-lg sm:text-xl"
            >
              <MdEmail />
              {data?.email}
            </a>
            <a
              href={`tel:${data?.phone}`}
              className="flex flex-row gap-2 justify-center items-center text-xl"
            >
              <FaSquarePhone />
              {formatPhoneNumber(data?.phone || "")}
            </a>
          </div>

          <div className="flex flex-col self-center text-center w-full">
            <h5 className="mx-auto sm:mx-0 mt-4 sm:mt-0 text-xl">
              {footerContent.followUs}
            </h5>
            <div className="flex mt-2 mx-auto justify-center sm:mx-0 gap-4">
              <a href={data?.github} target="_blank" rel="noreferrer">
                <BsGithub className="text-terciary text-4xl" />
              </a>
              <a href={data?.linkedIn} target="_blank" rel="noreferrer">
                <FaLinkedin className="text-terciary text-4xl" />
              </a>
            </div>
          </div>
        </div>
        <div className="flex w-full justify-center pb-2">
          <div className="mt-1 flex flex-wrap justify-center gap-3">
            {resumeLinks.map((item) => (
              <Link
                key={item.href}
                to={item.href}
                className="text-sm uppercase tracking-[0.18em] text-accent underline underline-offset-4 transition-colors hover:text-neutral"
              >
                {item.label}
              </Link>
            ))}
          </div>
        </div>
            <div className="mx-auto p-4">
              &copy; {currentYear} {data?.name}
            </div>
      </footer>
    </>
  );
};

export default Layout;

const styles = {
  container: "mx-auto",
  footerContainer: "flex flex-col bg-secondary text-light relative w-full border-t border-neutral/20 bg-secondary",
  logoContainer:
    "flex justify-center items-center shadow-2xl rounded-2xl relative",
};
